// 03 - Spinlocks: no lost update from every core; try_lock is refused while held.
// One suite, one file: it registers itself with the runner; there is no
// list of suites to keep in step with the files.
// GENERATED by micro-os-scaffold (--micro-test-plus).
#include <mtp_board.hpp>
#include "smp_helpers.hpp"

using namespace os::rtos;
using namespace mtp_smp;

namespace
{
  constexpr unsigned spin_increments = 20000;
  mtp_board::spinlock* g_spin = nullptr;
  volatile std::uint32_t g_spin_counter = 0;

  void*
  count_under_spinlock (void*)
  {
    for (unsigned i = 0; i < spin_increments; ++i)
      {
        g_spin->lock ();
        const std::uint32_t value = g_spin_counter;
        asm volatile ("" ::: "memory");
        g_spin_counter = value + 1;
        g_spin->unlock ();
      }
    return nullptr;
  }

  volatile unsigned g_held = 0;
  volatile unsigned g_release = 0;
  volatile unsigned g_done = 0;

  void*
  hold_spinlock (void*)
  {
    g_spin->lock ();
    store (g_held, 1u);
    while (load (g_release) == 0)
      {
        mtp_board::cpu_relax ();
      }
    g_spin->unlock ();
    store (g_done, 1u);
    return nullptr;
  }
} // namespace

mt::static_suite suite_spinlock{
  "03 - Spinlocks", mtp_board::runner (),
  [] (mt::suite& ts) {
    ts.test ("a spinlock: every core, no lost update", [] (auto& t) {
      mtp_board::spinlock lock;
      g_spin = &lock;
      g_spin_counter = 0;
      thread* threads[ncpu] = {};
      for (unsigned core = 0; core < ncpu; ++core)
        {
          threads[core] = spawn ("mtp-spin", count_under_spinlock, nullptr,
                                 static_cast<int> (core));
        }
      for (auto* th : threads)
        {
          finish (th);
        }
      t.expect (mt::eq (static_cast<std::uint32_t> (g_spin_counter),
                        static_cast<std::uint32_t> (ncpu * spin_increments)))
          << via ("%u increments, none lost", ncpu * spin_increments);
    });

    ts.test ("try_lock fails while another core holds the lock", [] (auto& t) {
      mtp_board::spinlock lock;
      g_spin = &lock;
      store (g_held, 0u);
      store (g_release, 0u);
      store (g_done, 0u);
      thread* th = spawn ("mtp-spin-hold", hold_spinlock, nullptr, 1);
      const bool held = wait_until (g_held, ms (100));
      const bool refused = held && !lock.try_lock ();
      store (g_release, 1u);
      const bool released = wait_until (g_done, ms (100));
      const bool taken = lock.try_lock ();
      if (taken)
        {
          lock.unlock ();
        }
      finish (th);
      t.expect (held) << "core 1 took the lock";
      t.expect (refused) << via ("core 0's try_lock () was refused");
      t.expect (released) << "core 1 released it";
      t.expect (taken) << "and core 0's try_lock () then succeeded";
    });
  }
};
